package com.autocare.platform.order;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.autocare.platform.gateway.identity.AuthTokens;
import com.autocare.platform.service.MerchantActor;
import com.autocare.platform.vehicle.VehicleOwner;
import com.fasterxml.jackson.databind.JsonNode;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Noncash service receipt: never manufactures a payment or an order completion. */
public class CouponServiceRedemption {
 final ReservationStore db;
 public CouponServiceRedemption(ReservationStore db){this.db=db;}
 Map<String,Object> authorization(long uc,boolean lock){var rows=db.jdbc.queryForList("SELECT * FROM coupon_service_authorization WHERE user_coupon_id=?"+(lock?" FOR UPDATE":""),uc);return rows.isEmpty()?null:rows.get(0);}
 Map<String,Object> receipt(long uc,boolean lock){var rows=db.jdbc.queryForList("SELECT * FROM coupon_service_redemption WHERE user_coupon_id=?"+(lock?" FOR UPDATE":""),uc);return rows.isEmpty()?null:rows.get(0);}
 static boolean matches(String code,Object hash){return hash instanceof String s&&MessageDigest.isEqual(AuthTokens.sha256(code).getBytes(StandardCharsets.US_ASCII),s.getBytes(StandardCharsets.US_ASCII));}
 String eligibility(Map<String,Object> r){return CouponTransactions.known(db,r)?CouponTransactions.eligibility(db,r,number(r,"merchant_id"),number(r,"project_id"),java.math.BigDecimal.ZERO,"SERVICE"):"SOURCE_UNKNOWN";}
 void scopeLocks(Map<String,Object> r){db.one("SELECT id FROM merchant WHERE id=? AND status=1 AND is_deleted=0 FOR UPDATE",r.get("merchant_id"));db.one("SELECT id FROM standard_project WHERE id=? AND status=1 AND is_deleted=0 FOR UPDATE",r.get("project_id"));db.one("SELECT id FROM merchant_project WHERE merchant_id=? AND project_id=? AND on_shelf=1 AND is_deleted=0 FOR UPDATE",r.get("merchant_id"),r.get("project_id"));}
 Map<String,Object> ownerLock(VehicleOwner a,long uc){db.owner(a,true);var r=CouponTransactions.own(db,a.id(),uc,false);if(!CouponTransactions.known(db,r))throw CouponTransactions.conflict();db.lockShop(number(r,"merchant_id"));scopeLocks(r);return CouponTransactions.own(db,a.id(),uc,true);}
 Map<String,Object> merchantLock(MerchantActor a,long uc){db.merchant(a,true);var meta=db.one("SELECT user_id FROM user_coupon WHERE id=? AND is_deleted=0",uc);var r=CouponTransactions.own(db,number(meta,"user_id"),uc,false);if(!CouponTransactions.known(db,r)||number(r,"merchant_id")!=a.merchantId())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"本店服务券不存在");if(receipt(uc,false)==null)scopeLocks(r);return CouponTransactions.own(db,number(meta,"user_id"),uc,true);}
 Map<String,Object> receiptView(Map<String,Object> r){return Map.of("redemption_id",number(r,"id"),"user_coupon_id",number(r,"user_coupon_id"),"coupon_id",number(r,"coupon_id"),"merchant_id",number(r,"merchant_id"),"project_id",number(r,"project_id"),"terms",db.parse(r.get("terms_json")),"redeemed_at",iso(r.get("redeemed_at")),"commission_amount",r.get("commission_amount").toString(),"rule_version",r.get("rule_version"));}
 public Map<String,Object> view(VehicleOwner a,long uc){return db.reads.execute(t->{db.owner(a,false);var r=CouponTransactions.own(db,a.id(),uc,false);boolean known=CouponTransactions.known(db,r);var code=authorization(uc,false);var done=receipt(uc,false);var out=new LinkedHashMap<String,Object>();out.put("user_coupon_id",uc);out.put("merchant_id",known?r.get("merchant_id"):null);out.put("terms",known?db.parse(r.get("terms_json")):null);out.put("source_known",known);out.put("eligibility",eligibility(r));out.put("authorization_revision",code==null?0L:number(code,"revision"));out.put("authorization_expires_at",code==null?null:iso(code.get("expires_at")));out.put("redemption",done==null?null:receiptView(done));return out;});}
 public JsonNode generate(VehicleOwner a,long uc,String key,JsonNode body){return db.writes.execute(new Actor("user",a.id()),"POST","/api/coupon/"+uc+"/service-authorization",key,body,()->{var r=ownerLock(a,uc);if(!eligibility(r).equals("ELIGIBLE"))throw CouponTransactions.conflict();},()->{var r=CouponTransactions.own(db,a.id(),uc,true);var prior=authorization(uc,true);long revision=prior==null?0:number(prior,"revision");if(revision!=body.get("expected_revision").longValue()||revision>=9007199254740990L)throw CouponTransactions.conflict();String code=UUID.randomUUID().toString().replace("-","");Instant deadline=db.now().plusSeconds(600),end=CouponInput.time(db.parse(r.get("terms_json")).get("valid_to"));if(end.isBefore(deadline))deadline=end;db.jdbc.update("INSERT INTO coupon_service_authorization(user_coupon_id,revision,code_hash,expires_at,created_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE revision=VALUES(revision),code_hash=VALUES(code_hash),expires_at=VALUES(expires_at),created_at=VALUES(created_at)",uc,revision+1,AuthTokens.sha256(code),time(deadline),time(db.now()));var after=Map.<String,Object>of("user_coupon_id",uc,"authorization_revision",revision+1,"expires_at",deadline.toString());var data=new LinkedHashMap<String,Object>(after);data.put("code",code);data.put("rule_version",CouponTransactions.SERVICE_RULE);return new Change("COUPON_SERVICE_AUTHORIZE","user_coupon",uc,Map.of("authorization_revision",revision),after,data);});}
 void verify(Map<String,Object> r,JsonNode body,boolean allowReceipt){long uc=number(r,"user_coupon_id");var code=authorization(uc,true);var done=receipt(uc,true);if(code==null||number(code,"revision")!=body.get("authorization_revision").longValue()||!matches(body.get("code").textValue(),code.get("code_hash")))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"服务券授权码无效或已更新");if(done!=null){if(!allowReceipt||!"USED".equals(r.get("status"))||number(done,"authorization_revision")!=number(code,"revision")||number(done,"merchant_id")!=number(r,"merchant_id")||number(done,"publication_revision")!=number(r,"publication_revision")||!CouponTransactions.SERVICE_RULE.equals(done.get("rule_version"))||!Objects.equals(done.get("user_id"),r.get("user_id"))||!Objects.equals(done.get("coupon_id"),r.get("coupon_id"))||!Objects.equals(done.get("project_id"),r.get("project_id"))||!db.parse(done.get("terms_json")).equals(db.parse(r.get("terms_json")))||db.jdbc.queryForObject("SELECT COUNT(*) FROM coupon_transaction_event WHERE user_coupon_id=? AND redemption_id=? AND kind='SERVICE_REDEEM' AND rule_version=?",Long.class,uc,done.get("id"),CouponTransactions.SERVICE_RULE)!=1L)throw CouponTransactions.conflict();return;}if(!eligibility(r).equals("ELIGIBLE")||!instant(code.get("expires_at")).isAfter(db.now()))throw CouponTransactions.conflict();}
 void guess(MerchantActor a,JsonNode body){long uc=body.get("user_coupon_id").longValue();long start=Math.floorDiv(db.now().getEpochSecond(),600)*600;String hash=AuthTokens.sha256(a.merchantId()+":"+uc);int result=db.transactions.execute(t->{var r=merchantLock(a,uc);var code=authorization(uc,true);var done=receipt(uc,true);if(done==null&&!eligibility(r).equals("ELIGIBLE"))throw CouponTransactions.conflict();var window=time(Instant.ofEpochSecond(start));db.jdbc.update("INSERT IGNORE INTO auth_rate_limit(scope,key_hash,window_start,attempts) VALUES('coupon_service_code',?,?,0)",hash,window);int attempts=db.jdbc.queryForObject("SELECT attempts FROM auth_rate_limit WHERE scope='coupon_service_code' AND key_hash=? AND window_start=? FOR UPDATE",Integer.class,hash,window);if(attempts>=5)return 429;if(code==null||number(code,"revision")!=body.get("authorization_revision").longValue()||!matches(body.get("code").textValue(),code.get("code_hash"))){db.jdbc.update("UPDATE auth_rate_limit SET attempts=attempts+1 WHERE scope='coupon_service_code' AND key_hash=? AND window_start=?",hash,window);return 422;}verify(r,body,true);return 0;});if(result==429)throw new OrderRedemption.RateLimited(Math.max(1,(int)(start+600-db.now().getEpochSecond())));if(result!=0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"服务券授权码无效或已更新");}
 public JsonNode redeem(MerchantActor a,String key,JsonNode body){com.autocare.platform.common.write.WriteIntegrityService.normalizeKey(key);guess(a,body);long uc=body.get("user_coupon_id").longValue();var canonical=body.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)canonical).remove("code");((com.fasterxml.jackson.databind.node.ObjectNode)canonical).put("code_digest",AuthTokens.sha256(body.get("code").textValue()));return db.writes.execute(new Actor("staff_account",a.staffId()),"POST","/api/merchant/coupons/service-redeem",key,canonical,()->{var r=merchantLock(a,uc);verify(r,body,true);long start=Math.floorDiv(db.now().getEpochSecond(),600)*600;db.jdbc.update("INSERT IGNORE INTO auth_rate_limit(scope,key_hash,window_start,attempts) VALUES('coupon_service_code',?,?,0)",AuthTokens.sha256(a.merchantId()+":"+uc),time(Instant.ofEpochSecond(start)));int attempts=db.jdbc.queryForObject("SELECT attempts FROM auth_rate_limit WHERE scope='coupon_service_code' AND key_hash=? AND window_start=? FOR UPDATE",Integer.class,AuthTokens.sha256(a.merchantId()+":"+uc),time(Instant.ofEpochSecond(start)));if(attempts>=5)throw new OrderRedemption.RateLimited(Math.max(1,(int)(start+600-db.now().getEpochSecond())));},()->{var r=merchantLock(a,uc);var done=receipt(uc,true);if(done!=null){var same=receiptView(done);return new Change("COUPON_SERVICE_REPLAY","user_coupon",uc,same,same,same,false);}long redemption=db.insert("INSERT INTO coupon_service_redemption(user_coupon_id,user_id,coupon_id,publication_revision,merchant_id,project_id,staff_id,authorization_revision,terms_json,redeemed_at,commission_amount,rule_version) VALUES(?,?,?,?,?,?,?,?,?,?,0.00,?)",uc,r.get("user_id"),r.get("coupon_id"),r.get("publication_revision"),a.merchantId(),r.get("project_id"),a.staffId(),body.get("authorization_revision").longValue(),r.get("terms_json").toString(),time(db.now()),CouponTransactions.SERVICE_RULE);if(db.jdbc.update("UPDATE user_coupon SET status='USED',used_at=?,reserved_until=NULL WHERE id=? AND status='AVAILABLE' AND order_id IS NULL",time(db.now()),uc)!=1)throw CouponTransactions.conflict();CouponTransactions.event(db,uc,"SERVICE_REDEEM","service:"+redemption,null,null,null,redemption,"AVAILABLE","USED",CouponTransactions.SERVICE_RULE);var after=receiptView(receipt(uc,true));return new Change("COUPON_SERVICE_REDEEM","user_coupon",uc,Map.of("status","AVAILABLE"),after,after);});}
 public Map<String,Object> list(MerchantActor a,int page,int size){return db.reads.execute(t->{db.merchant(a,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM coupon_service_redemption WHERE merchant_id=?",Long.class,a.merchantId());var rows=db.jdbc.queryForList("SELECT * FROM coupon_service_redemption WHERE merchant_id=? ORDER BY id DESC LIMIT ? OFFSET ?",a.merchantId(),size,(page-1)*size);return page(rows.stream().map(this::receiptView).toList(),count,page,size);});}
 public Map<String,Object> preview(MerchantActor a,JsonNode body){guess(a,body);return db.transactions.execute(t->{long uc=body.get("user_coupon_id").longValue();var r=merchantLock(a,uc);verify(r,body,true);var auth=authorization(uc,true);var done=receipt(uc,true);var project=db.one("SELECT project_name FROM standard_project WHERE id=?",r.get("project_id"));var out=new LinkedHashMap<String,Object>();out.put("user_coupon_id",uc);out.put("merchant_id",a.merchantId());out.put("project_id",number(r,"project_id"));out.put("project_name",project.get("project_name"));out.put("terms",db.parse(r.get("terms_json")));out.put("authorization_revision",number(auth,"revision"));out.put("authorization_expires_at",iso(auth.get("expires_at")));out.put("redemption",done==null?null:receiptView(done));out.put("can_redeem",done==null);return out;});}
}
